import { Plugin } from "@opencode/plugin";
import { Plugin as EffectPlugin } from "@opencode/plugin/effect";
import { fromPromise } from "@opencode/plugin/promise/adapter";
import { Effect } from "effect";
import { randomUUID } from "node:crypto";
import { watchFromHub } from "./platform/events.js";
import { hub, openInProcess, permissions as domains, sharedState } from "./platform/hub.js";
import { builtVersions, versionNotice } from "./platform/version.js";
import { addSchedulingTools, cancelScheduled, dueJob, isScheduled } from "./scheduling/index.js";
import { addPersonTools, ANSWER_TOOL, asksPermission, asksQuestion, formsShown, joinRelay, noticeCutOff, pendingOf, pendingQuestions, personEvents, portsAt, registerPersonRpc, relayQuestions, } from "./person/index.js";
import { addSkill } from "./skill.js";
import { addTreeTools, wakeMissed, dirtyOf, headOf, inspectWorktree, onFork, onIdle, pruneExpired, readLimits, readRemovedOptions, registerTreeRpc, shapeContext, treeEvents, waitsOn, } from "./tree/index.js";
const gate = sharedState("spawning", () => ({ reserved: new Set(), turn: Promise.resolve() }));
const inbox = sharedState("inbox", () => new Map());
const shown = sharedState("formsShown", () => new Map());
const jobs = [
    dueJob,
    (owner, claimed) => wakeMissed(owner.later, claimed),
];
const { join, track } = openInProcess(jobs);
const permissions = domains;
const { watched } = hub;
const watchState = { seen: watched.seen, inbox };
const personState = { ...watched, forms: hub.forms, shown };
const outside = waitsOn(asksPermission, asksQuestion, isScheduled);
const eventModules = [treeEvents(watchState, outside), personEvents(personState)];
export const courier = () => Plugin.define({
    id: "courier",
    setup: async (ctx) => {
        const log = (message) => console.error(message);
        try {
            const notice = versionNotice(builtVersions(), ctx.app);
            if (notice)
                log(notice);
        }
        catch (error) {
            log(`courier: cannot compare the OpenCode version with the one it was built against: ${String(error)}`);
        }
        const questionPorts = {
            storage: ctx.storage,
            session: ctx.session,
            directory: ctx.location.directory,
            now: Date.now,
            timing: { closingGraceMs: 30_000, passingWaitMs: 30_000, relayWaitMs: 30_000, dismissalGraceMs: 2_000 },
            newID: () => `question_${randomUUID()}`,
            log,
        };
        const { limits, problems } = readLimits(ctx.options);
        for (const problem of [...problems, ...readRemovedOptions(ctx.options)])
            log(`courier: ${problem}`);
        const roles = new Map();
        const ports = {
            limits,
            gate,
            roles,
            log,
            session: ctx.session,
            agent: ctx.agent,
            worktree: ctx.worktree,
            storage: ctx.storage,
            directory: ctx.location.directory,
            projectID: ctx.location.project.id,
            now: Date.now,
            models: async () => (await ctx.model.list()).data.map((model) => ({
                providerID: model.providerID,
                id: model.id,
                context: model.limit.context,
                variants: model.variants.map((variant) => variant.id),
            })),
            defaultModel: async () => {
                const { data } = await ctx.model.default();
                return data ? { providerID: data.providerID, id: data.id } : undefined;
            },
            head: headOf,
            dirty: dirtyOf,
            pending: async (sessionID) => {
                const [requests, questions] = await Promise.all([
                    pendingOf(permissions(), sessionID),
                    pendingQuestions(ctx.storage, sessionID),
                ]);
                return [...requests, ...questions];
            },
            forms: (sessionID) => Promise.resolve(formsShown(shown, sessionID)),
        };
        const cleanupPorts = { ...ports, inspect: inspectWorktree };
        const answerPorts = { storage: ctx.storage, permissions, assert: (input) => ctx.permission.assert(input) };
        const later = {
            storage: ctx.storage,
            session: ctx.session,
            now: Date.now,
            newID: () => `later_${randomUUID()}`,
            log,
        };
        const stopPorts = { courier: ports, cancelScheduled: (sessionID) => cancelScheduled(later, sessionID), cleanup: cleanupPorts };
        await ctx.tool.transform((tools) => {
            addTreeTools(tools, { courier: ports, cleanup: cleanupPorts, stop: stopPorts });
            addPersonTools(tools, { answer: answerPorts, questions: questionPorts, waiting: watched.waiting });
            addSchedulingTools(tools, later);
        });
        await ctx.skill.transform(addSkill);
        await Promise.resolve()
            .then(() => registerTreeRpc(ctx.rpc, stopPorts))
            .then(() => registerPersonRpc(ctx.rpc, { questions: questionPorts, permissions }))
            .catch((error) => log(`courier rpc: not registered, the TUI part shows nothing and cannot stop: ${String(error)}`));
        const instructions = ctx.session.instructions;
        await ctx.session.hook("context", (event) => shapeContext({ storage: ctx.storage, session: ctx.session, limits, roles, hiddenFromLeaf: [ANSWER_TOOL], instructions, log }, event));
        const pruned = pruneExpired(ctx.storage, Date.now()).catch((error) => log(`courier roster prune: ${String(error)}`));
        const leaveRelay = joinRelay(questionPorts);
        const noticed = noticeCutOff(questionPorts).catch((error) => questionPorts.log(`courier question: stored questions: ${String(error)}`));
        const watchPorts = {
            storage: ctx.storage,
            session: ctx.session,
            event: ctx.event,
            permissions,
            now: questionPorts.now,
            log: later.log,
        };
        await Promise.resolve()
            .then(() => ctx.session.hook("experimental.idle", (event) => onIdle(watchPorts, watchState.seen, outside, event).then(() => undefined)))
            .catch((error) => log(`courier idle: not registered, a child that ends without a report is not reminded: ${String(error)}`));
        await Promise.resolve()
            .then(() => ctx.session.hook("fork", (event) => onFork({ storage: ctx.storage, session: ctx.session, log }, watchState.seen, event).then(() => undefined)))
            .catch((error) => log(`courier fork: not registered, a fork of a session in a tree is not told that courier did not start it: ${String(error)}`));
        watchFromHub(hub, eventModules);
        const member = {
            directory: ctx.location.directory,
            location: ctx.location,
            permission: ctx.permission,
            later,
            watch: watchPorts,
            questions: questionPorts,
            log,
        };
        const leaveHub = join(member);
        track(member, pruned);
        track(member, noticed);
        return async () => {
            const leftHub = leaveHub();
            leaveRelay();
            await leftHub;
        };
    },
});
export default EffectPlugin.define({
    id: "courier",
    effect: (host) => Effect.gen(function* () {
        yield* fromPromise(courier()).effect(host);
        yield* relayQuestions(host, portsAt(host.location));
    }),
});

export { personEvents } from "./events.js";
export { formsShown } from "./form.js";
export { asksPermission, pendingOf } from "./permission.js";
export { registerPersonRpc } from "./rpc-handlers.js";
export { asksQuestion, joinRelay, noticeCutOff, pendingQuestions, portsAt, relayQuestions } from "./question/index.js";
export { addPersonTools, ANSWER_TOOL } from "./tools.js";

import { deliverDue } from "./later.js";
export { cancel, cancelScheduled, deliverDue, isScheduled, schedule, scheduledFor } from "./later.js";
export { addSchedulingTools } from "./tools.js";
export const dueJob = (owner, claimed) => deliverDue(owner.later, claimed);

export { dirtyOf, headOf, inspectWorktree } from "./cleanup.js";
export { shapeContext } from "./context.js";
export { lineageIn, nativeRootOf, readLimits, readRemovedOptions } from "./domain.js";
export { treeEvents, waitsOn } from "./events.js";
export { onFork } from "./fork.js";
export { onIdle } from "./nudge.js";
export { allEntries, answeringTop, lineage, pruneExpired, RETENTION_MS } from "./roster.js";
export { subtree } from "./subtree.js";
export { registerTreeRpc } from "./rpc-handlers.js";
export { addTreeTools } from "./tools.js";
export { wakeMissed } from "./wake.js";

export { answerForPerson, answerQuestion, asksQuestion, noticeCutOff, pendingQuestions } from "./answer.js";
export { eventsFollowed, eventsLeft, formShown, formsMayHaveBeenMissed, joinRelay, locationClosing, shutdownReportedAt } from "./lifecycle.js";
export { byCodeUnit } from "./pure.js";
export { relayQuestions } from "./relay.js";
export { isQuestion, MAX_STORED, portsAt, QUESTION_TOOL } from "./shared.js";
